/* Graph Paper Games — pencil stroke sounds.
   Real pencil-on-paper strokes cut from "pencil" by freesound_community (Pixabay Content License,
   free for commercial use, no attribution required). Every move plays real strokes, picked at
   random so no two moves sound exactly alike, timed to the animation on screen.
   Four in a Row uses a plastic-disc drop sound made in code for this app. */
(function(){
'use strict';
const SHORT=[[0.0, 0.175], [0.225, 0.215], [0.49, 0.145], [0.685, 0.165], [0.9, 0.175], [1.125, 0.185], [1.36, 0.175]], LONG=[[1.5851, 0.325], [1.9601, 0.355], [2.3651, 0.415], [2.8301, 0.335], [3.2151, 0.325], [3.5901, 0.335]];   // [start, length] in seconds inside the sprite below
const BASE=[[0.0, 0.36], [0.42, 0.36], [0.84, 0.36]], DISC=[[1.26, 0.36], [1.68, 0.36], [2.1, 0.36]];   // disc drops: onto the board's base / onto another disc
const DROP='data:audio/mpeg;base64,';
const DATA='data:audio/mpeg;base64,';
const KEY='gpg-sound';
let on=true;
try{on=localStorage.getItem(KEY)!=='off'}catch(e){}
let ctx=null,buf=null,drops=null,loading=null;

// decode an embedded sound directly (no fetch, so nothing can block it)
function decode(uri){
  const bin=atob(uri.slice(uri.indexOf(',')+1)),a=new Uint8Array(bin.length);
  for(let i=0;i<bin.length;i++)a[i]=bin.charCodeAt(i);
  return new Promise((ok,no)=>ctx.decodeAudioData(a.buffer,ok,no));
}
function init(){
  if(ctx)return true;
  const AC=window.AudioContext||window.webkitAudioContext;
  if(!AC)return false;
  ctx=new AC();
  loading=Promise.all([decode(DATA).then(b=>{buf=b}).catch(()=>{}),decode(DROP).then(b=>{drops=b}).catch(()=>{})]);
  return true;
}
// Phones keep audio locked until the first tap; unlock and load then.
function unlock(){if(init()&&ctx.state==='suspended')ctx.resume()}
['pointerdown','touchstart','keydown'].forEach(ev=>window.addEventListener(ev,unlock,{passive:true}));


function play(b,seg,at,rate,vol){
  if(!b)return;
  const src=ctx.createBufferSource();src.buffer=b;
  src.playbackRate.value=rate*(.94+Math.random()*.12);   // tiny pressure/speed variation
  const g=ctx.createGain();g.gain.value=vol*(.85+Math.random()*.15);
  src.connect(g);g.connect(ctx.destination);
  src.start(at,seg[0],seg[1]/rate);
}
const last={};
function one(name,list,b,at,rate=1,vol=1){
  let i;do{i=Math.floor(Math.random()*list.length)}while(list.length>1&&i===last[name]);
  last[name]=i;play(b,list[i],at,rate,vol);
}

/* Public: what each move sounds like.
   ttt: info 'x' or 'o'.  c4: info 'base' or 'disc'.  dab: info = boxes claimed by this line. */
function scratch(style,info){
  if(!on||!init())return;
  if(ctx.state==='suspended')ctx.resume();
  const go=()=>{
    const t=ctx.currentTime+.005;
    if(style==='ttt'){
      if(info==='x'){one('s',SHORT,buf,t);one('s',SHORT,buf,t+.16)}   // X: two strokes, like the drawing
      else one('l',LONG,buf,t);                                       // O: one round stroke
    }else if(style==='c4'){
      one(info==='base'?'b':'d',info==='base'?BASE:DISC,drops,t);     // disc slides in and clacks down
    }else{
      // Dots & Boxes has many moves, so its sounds stay soft and calm
      one('s',SHORT,buf,t,1,.55);                                     // line: one light pencil stroke
      const n=Math.min(+info||0,2);                                   // box claimed: one smooth shading stroke
      for(let k=0;k<n;k++)one('l',LONG,buf,t+.22+k*.18,.88,.6);
    }
  };
  (buf&&drops)?go():loading&&loading.then(go);
}

window.Sound={
  scratch,
  isOn:()=>on,
  set(v){on=!!v;try{localStorage.setItem(KEY,on?'on':'off')}catch(e){}}
};
})();
